import os
def esc(x): return x.replace('\\','\\\\').replace('"','\\"')
base=os.path.join(os.path.dirname(os.path.abspath(__file__)),"..","Slowed")
for i,l in enumerate(["es"]+LANGS):
    d=os.path.join(base,l+".lproj"); os.makedirs(d,exist_ok=True)
    with open(os.path.join(d,"Localizable.strings"),"w") as f:
        f.write("/* Slowed — %s */\n"%l)
        for k,v in T.items():
            val = k if l=="es" else v[i-1]
            f.write('"%s" = "%s";\n'%(esc(k),esc(val)))
